Translate("zhCN", "durotar", {
	title = "杜隆塔尔",
	sections = {
		{
			title = "概述",
			text = [=[杜隆塔尔是{link:orcs}兽人{/link}的家园，一片位于{link:kalimdor}卡利姆多{/link}东岸、赤红而破碎的土地。这里的土壤干裂，峡谷陡峭，烈日毫不留情地炙烤着大地。兽人欣然选择了它，因为它严酷的美让他们想起自己失去的世界。大酋长{link:thrall}萨尔{/link}在这里建起了他的都城{link:orgrimmar}奥格瑞玛{/link}，{link:horde}部落{/link}的年轻人也在这里接受考验，然后被派往世界各地。这是一片只在名义上和平的土地。敌人从海上、从峡谷、从它自己洞穴的阴影中窥视着它。]=],
		},
		{
			title = "起源",
			text = [=[在{link:orcs}兽人{/link}到来之前，这片土地被视为{link:the-barrens}贫瘠之地{/link}的一部分，{link:razormane-quilboar}钢鬃部族{/link}的{link:quilboar}野猪人{/link}在此自由游荡。{link:battle-of-mount-hyjal}海加尔山之战{/link}之后，{link:thrall}萨尔{/link}率领他的人民向东来到海岸，宣布怒水河与大海之间的土地归他们所有。他以父亲、{link:frostwolf-clan}霜狼氏族{/link}酋长杜隆坦之名，将其命名为杜隆塔尔。{link:tauren}牛头人{/link}和{link:darkspear-trolls}暗矛巨魔{/link}为这个新国家贡献了力量，兽人则把{link:bristleback-quilboar}钢鬃野猪人{/link}赶出了这片土地，只给他们留下了西部边缘。]=],
		},
