	sections = {
		{
			title = "概述",
			text = [=[暗矛群岛位于{link:durotar}杜隆塔尔{/link}海岸外，饱受外海风暴的侵袭。{link:trolls}巨魔{/link}们视其为圣地，因为他们的灵魂之力在那里十分强大，{link:darkspear-trolls}暗矛巨魔{/link}会聚集在岛上举行仪式。如今{link:alliance}联盟{/link}企图在这些岛屿上建立据点，离{link:orcs}兽人{/link}家园的海岸近在咫尺。暗矛巨魔和他们在{link:horde}部落{/link}中的盟友不会让他们留下。在废墟、营地、古老的塔楼和沉船海湾之间，双方为争夺群岛和部族的一件神圣遗物而战。]=],
