Translate("zhCN", "daelin-proudmoore", {
	title = "戴林·普罗德摩尔",
	subtitle = "库尔提拉斯海军上将",
	allegiance = "库尔提拉斯 · 普罗德摩尔家族",
	aliases = { "戴林", "普罗德摩尔将军" },
	sections = {
		{
			title = "概述",
			text = [=[戴林·普罗德摩尔是{link:kul-tiras}库尔提拉斯{/link}的海军上将，也是{link:jaina-proudmoore}吉安娜·普罗德摩尔{/link}的父亲。在{link:second-war}第二次战争{/link}中，他的舰队为{link:alliance}联盟{/link}称霸海洋，他也成为{link:humans}人类{/link}伟大的英雄之一。他从未因那场战争原谅{link:orcs}兽人{/link}。当他得知兽人已在{link:kalimdor}卡利姆多{/link}海岸定居时，他率领一支无敌舰队前来消灭他们，并在这次尝试中丧生。]=],
		},
		{
			title = "意义",
			text = [=[戴林的战争是{link:durotar}杜隆塔尔{/link}这个年轻国家所面临的第一个重大威胁。他的死在父女之间划下了一道界线，也在两种看待{link:orcs}兽人{/link}的方式之间划下了一道界线：一种认为他们是能够改变的民族，另一种认为他们是永远不会改变的怪物。他的部下至今仍以他的名义据守着{link:tiragarde-keep}提拉加德城堡{/link}。]=],
		},
		{
			title = "联盟的海军上将",
			text = [=[{link:kul-tiras}库尔提拉斯{/link}是一个水手的王国，普罗德摩尔家族统领着它的舰队。{link:first-war}第一次战争{/link}之后{link:horde}部落{/link}向北进军时，戴林率领他的海军加入了{link:lordaeron}洛丹伦{/link}{link:alliance}联盟{/link}。他的战舰在公海上与{link:orcs}兽人{/link}舰队交战，把联盟的军队从一处海岸运往另一处海岸。库尔提拉斯在船只和人员上付出了惨重的代价。戴林终生都记得这份代价。]=],
		},
		{
			title = "无敌舰队",
			text = [=[{link:third-war}第三次战争{/link}之后，他的女儿{link:jaina-proudmoore}吉安娜{/link}带领{link:lordaeron}洛丹伦{/link}的幸存者向西来到{link:kalimdor}卡利姆多{/link}，建起了{link:theramore-isle}塞拉摩城{/link}。她在那里与{link:thrall}萨尔{/link}缔结了和平。戴林不肯接受。他率领一支庞大的舰队驶向卡利姆多，在{link:durotar}杜隆塔尔{/link}海岸建起了{link:tiragarde-keep}提拉加德城堡{/link}，向{link:orcs}兽人{/link}和{link:echo-isles}回音群岛{/link}的{link:trolls}巨魔{/link}开战。{link:horde}部落{/link}作出了回应。它的战士攻破了城堡，最终把战火烧到了塞拉摩的城墙下。吉安娜袖手旁观。在战斗中，海军上将阵亡了。]=],
		},
		{
			title = "事迹",
			text = [=[• 他在{link:second-war}第二次战争{/link}中指挥{link:kul-tiras}库尔提拉斯{/link}的海军。
• 他在{link:durotar}杜隆塔尔{/link}海岸建起了{link:tiragarde-keep}提拉加德城堡{/link}。
• 他违背女儿缔结的和平，向{link:horde}部落{/link}开战。
• 他留下了让战争在他死后继续下去的命令。]=],
		},
		{ title = "未载之事", text = "这里关于戴林在战争之前的生活记载甚少。本条目只记录史书和他自己的命令所揭示的东西。" },
	},
	chapters = {
		{
			title = "海军将军的命令",
			hint = "阅读保存在提拉加德城堡的密封命令。",
			text = [=[在{link:lieutenant-benedict}本尼迪克上尉{/link}的物品中，有一个盖着海军上将印章的陈旧信封。里面装着戴林离开{link:kul-tiras}库尔提拉斯{/link}之前就写好的命令。它们表明他早已周密部署，还会有更多的部下跟随第一支舰队前往{link:durotar}杜隆塔尔{/link}。{link:razor-hill}剃刀岭{/link}的{link:orcs}兽人{/link}从中读出了一个简单的警告：海军上将死了，但他的战争没有结束。]=],
		},
	},
	mentions = {
		{ text = "消灭{link:illidan-stormrage}背叛者{/link}" },
		{ text = "普罗德摩尔将军的命令，送交{link:gar-thok}加索克{/link}" },
		{ text = "普罗德摩尔将军的命令，送往{link:orgrimmar}奥格瑞玛{/link}" },
	},
	bonds = {
		{ id = "jaina-proudmoore", name = "吉安娜·普罗德摩尔", note = "他的女儿" },
		{ id = "lieutenant-benedict", name = "本尼迪克上尉", note = "继续着他的战争" },
		{ id = "thrall", name = "萨尔", note = "他的敌人" },
	},
})
